import 'package:flutter/material.dart';import '../../home/home_config_service.dart';
class HomeAdminPage extends StatefulWidget{const HomeAdminPage({super.key});@override State<HomeAdminPage> createState()=>_H();}
class _H extends State<HomeAdminPage>{final s=HomeConfigService();final title=TextEditingController(),sub=TextEditingController(),bt=TextEditingController(),bs=TextEditingController();bool cats=true,banner=true,popular=true;bool loaded=false;void fill(Map<String,dynamic> d){if(loaded)return;loaded=true;title.text=d['title']??'';sub.text=d['subtitle']??'';bt.text=d['bannerTitle']??'';bs.text=d['bannerSubtitle']??'';cats=d['showCategories']??true;banner=d['showBanner']??true;popular=d['showPopular']??true;}Future<void> save()async{await s.save({'title':title.text.trim(),'subtitle':sub.text.trim(),'bannerTitle':bt.text.trim(),'bannerSubtitle':bs.text.trim(),'showCategories':cats,'showBanner':banner,'showPopular':popular});if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Tampilan Home diperbarui realtime')));}@override Widget build(BuildContext c)=>StreamBuilder(stream:s.watch(),builder:(c,x){final d=HomeConfigService.defaults..addAll(x.data?.data()??{});fill(d);return Scaffold(appBar:AppBar(title:const Text('Pengaturan Home')),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('Atur tampilan aplikasi tanpa update APK',style:TextStyle(fontWeight:FontWeight.bold,fontSize:18)),const SizedBox(height:16),TextField(controller:title,decoration:const InputDecoration(labelText:'Nama aplikasi')),TextField(controller:sub,decoration:const InputDecoration(labelText:'Subjudul')),SwitchListTile(value:banner,onChanged:(v)=>setState(()=>banner=v),title:const Text('Tampilkan banner')),TextField(controller:bt,decoration:const InputDecoration(labelText:'Judul banner')),TextField(controller:bs,decoration:const InputDecoration(labelText:'Isi banner')),SwitchListTile(value:cats,onChanged:(v)=>setState(()=>cats=v),title:const Text('Kategori')),SwitchListTile(value:popular,onChanged:(v)=>setState(()=>popular=v),title:const Text('Produk populer')),const SizedBox(height:12),FilledButton.icon(onPressed:save,icon:const Icon(Icons.save),label:const